-- 成果作者单位规范：维护规范名称、别名和成果作者的规范绑定。
BEGIN;

CREATE TABLE IF NOT EXISTS "科研单位规范" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "规范名称" varchar(300) NOT NULL,
    "统一社会信用代码" varchar(50),
    "状态" varchar(10) NOT NULL DEFAULT '启用',
    "备注" varchar(1000),
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研单位规范" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_科研单位规范_名称" UNIQUE ("规范名称"),
    CONSTRAINT "ck_科研单位规范_状态" CHECK ("状态" IN ('启用','停用'))
);

CREATE TABLE IF NOT EXISTS "科研单位别名" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "规范单位编号" bigint NOT NULL,
    "别名" varchar(300) NOT NULL,
    "来源" varchar(100),
    "是否启用" boolean NOT NULL DEFAULT TRUE,
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研单位别名" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_科研单位别名_名称" UNIQUE ("别名")
);

CREATE INDEX IF NOT EXISTS "ix_科研单位别名_规范单位"
    ON "科研单位别名" ("规范单位编号", "是否启用");

ALTER TABLE "科研成果作者核验"
    ADD COLUMN IF NOT EXISTS "规范单位编号" bigint,
    ADD COLUMN IF NOT EXISTS "单位规范状态" varchar(10) NOT NULL DEFAULT '待规范';

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_科研成果作者核验_单位规范状态') THEN
        ALTER TABLE "科研成果作者核验"
            ADD CONSTRAINT "ck_科研成果作者核验_单位规范状态" CHECK ("单位规范状态" IN ('待规范','已规范','无需规范'));
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS "ix_科研成果作者核验_单位规范"
    ON "科研成果作者核验" ("规范单位编号", "单位规范状态");

UPDATE "系统迁移版本"
   SET "版本" = 52,
       "脚本" = '001-052',
       "检查摘要" = '增加科研单位规范字典和成果作者单位绑定'
 WHERE "编号" = 1;

COMMIT;
